# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.parsing import parse_span

OPEN = parse_span("09:00-17:00")

def gaps_for(*texts):
    spans = [parse_span(text) for text in texts]
    return find_gaps(spans, OPEN)

class FindGapsTests(unittest.TestCase):
    def test_middle_gap(self):
        result = gaps_for("09:00-12:00", "13:00-17:00")
        want = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(result, want)

    def test_nobody_working(self):
        result = gaps_for()
        want = ["gap 09:00-17:00 (480 min)"]
        self.assertEqual(result, want)

    def test_full_coverage(self):
        self.assertEqual(gaps_for("09:00-17:00"), [])

    def test_overlap_and_touching(self):
        result = gaps_for(
            "09:00-13:00", "12:00-15:00", "15:00-17:00"
        )
        self.assertEqual(result, [])

    def test_edges_and_order(self):
        result = gaps_for("14:00-15:00", "10:00-12:30")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 12:30-14:00 (90 min)",
            "gap 15:00-17:00 (120 min)"
        ])

    def test_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            gaps_for("08:00-10:00")
        with self.assertRaises(ValueError):
            gaps_for("16:00-17:30")

if __name__ == "__main__":
    unittest.main()
